       span = #{chart.span},
       height = #{chart.height}

WHERE
        id = #{chart.id}

mapper.select:
select vc.* from visual_chart vc
left join asset_asset t on vc.var_id = t.id
left join monitor_endpoint t on vc.var_id = t.id
where 1=1
and t.model_id = #{id}
and t.module_id= #{id}
